using DriveOS.Modules.CurriculumPedagogy.Domain.Readiness;using DriveOS.SharedKernel.Identifiers;
namespace DriveOS.UnitTests.Modules.CurriculumPedagogy.Readiness;
public sealed class PedagogicalReadinessDecisionTests{[Fact]public void Ready_decision_raises_ready_event(){var r=PedagogicalReadinessDecision.Record(PedagogicalReadinessDecisionId.New(),new OrganizationId(Guid.NewGuid()),new PersonId(Guid.NewGuid()),new TrainingPathId(Guid.NewGuid()),PedagogicalReadinessDecisionStatus.Ready,"Compétences et bilan validés.",null,new UserId(Guid.NewGuid()),DateTimeOffset.UtcNow);Assert.True(r.IsSuccess);Assert.Equal(2,r.Value.DomainEvents.Count);}[Fact]public void Ready_with_conditions_requires_conditions(){var r=PedagogicalReadinessDecision.Record(PedagogicalReadinessDecisionId.New(),new OrganizationId(Guid.NewGuid()),new PersonId(Guid.NewGuid()),new TrainingPathId(Guid.NewGuid()),PedagogicalReadinessDecisionStatus.ReadyWithConditions,"Avis favorable sous réserve.",null,new UserId(Guid.NewGuid()),DateTimeOffset.UtcNow);Assert.True(r.IsFailure);}}
